// LRU Cache — O(1) get and put
class LRUCache {
  #cap;
  #map;   // key -> node
  #head;  // dummy MRU sentinel
  #tail;  // dummy LRU sentinel

  constructor(capacity) {
    this.#cap  = capacity;
    this.#map  = new Map();
    this.#head = { key: null, val: null, prev: null, next: null };
    this.#tail = { key: null, val: null, prev: null, next: null };
    this.#head.next = this.#tail;
    this.#tail.prev = this.#head;
  }

  #remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  #insertFront(node) {
    node.next       = this.#head.next;
    node.prev       = this.#head;
    this.#head.next.prev = node;
    this.#head.next      = node;
  }

  // O(1)
  get(key) {
    if (!this.#map.has(key)) return -1;
    const node = this.#map.get(key);
    this.#remove(node);
    this.#insertFront(node);
    return node.val;
  }

  // O(1)
  put(key, val) {
    if (this.#map.has(key)) {
      const node = this.#map.get(key);
      node.val   = val;
      this.#remove(node);
      this.#insertFront(node);
    } else {
      if (this.#map.size === this.#cap) {
        const lru = this.#tail.prev;  // evict LRU
        this.#remove(lru);
        this.#map.delete(lru.key);
      }
      const node = { key, val, prev: null, next: null };
      this.#insertFront(node);
      this.#map.set(key, node);
    }
  }
}

const lru = new LRUCache(3);
lru.put(1, 'a'); lru.put(2, 'b'); lru.put(3, 'c');
console.log(lru.get(1));   // 'a'  — 1 becomes MRU, order: 1,3,2
lru.put(4, 'd');            // evict LRU (2), order: 4,1,3
console.log(lru.get(2));   // -1   — 2 was evicted
console.log(lru.get(3));   // 'c'  — 3 becomes MRU, order: 3,4,1
console.log(lru.get(4));   // 'd'

// LFU Cache — O(1) get and put
class LFUCache {
  #cap; #minFreq;
  #keyMap;   // key -> {value, freq}
  #freqMap;  // freq -> Set<key> (insertion-order = LRU within freq)

  constructor(capacity) {
    this.#cap     = capacity;
    this.#minFreq = 0;
    this.#keyMap  = new Map();
    this.#freqMap = new Map();
  }

  #incrFreq(key) {
    const entry = this.#keyMap.get(key);
    const f     = entry.freq;
    this.#freqMap.get(f).delete(key);
    if (this.#freqMap.get(f).size === 0) {
      this.#freqMap.delete(f);
      if (this.#minFreq === f) this.#minFreq++;
    }
    entry.freq++;
    if (!this.#freqMap.has(entry.freq)) this.#freqMap.set(entry.freq, new Set());
    this.#freqMap.get(entry.freq).add(key);
  }

  // O(1)
  get(key) {
    if (!this.#keyMap.has(key)) return -1;
    this.#incrFreq(key);
    return this.#keyMap.get(key).value;
  }

  // O(1)
  put(key, value) {
    if (this.#cap <= 0) return;
    if (this.#keyMap.has(key)) {
      this.#keyMap.get(key).value = value;
      this.#incrFreq(key);
      return;
    }
    if (this.#keyMap.size >= this.#cap) {
      const lfuBucket = this.#freqMap.get(this.#minFreq);
      const evict     = lfuBucket.values().next().value; // oldest in min-freq bucket
      lfuBucket.delete(evict);
      this.#keyMap.delete(evict);
    }
    this.#keyMap.set(key, { value, freq: 1 });
    if (!this.#freqMap.has(1)) this.#freqMap.set(1, new Set());
    this.#freqMap.get(1).add(key);
    this.#minFreq = 1; // new key always has freq 1
  }
}

// LRU vs LFU comparison:
// Sequence: put(1,a) put(2,b) put(3,c) get(1) get(1) put(4,d)
// LRU evicts: 2 (least recently used)
// LFU evicts: 3 (freq 0 vs 1's freq 2, 2's freq 0 — 2 or 3 tie, LRU within → 2)
// LFU is better when access patterns have stable hot keys (1 accessed twice)

const lfu = new LFUCache(3);
lfu.put(1,'a'); lfu.put(2,'b'); lfu.put(3,'c');
lfu.get(1); lfu.get(1); // freq[1]=2, freq[2]=freq[3]=0 (1 put each)
lfu.put(4,'d');          // evict min-freq bucket (freq=1): first inserted = 2
console.log(lfu.get(2)); // -1 (evicted)
console.log(lfu.get(3)); // 'c' (still present, freq 1)
